import collections
def graph_stats(n):
    x=X[n]
    cyc=[]; seen=set()
    for st in range(5):
        if st in seen: continue
        path=[]; cur=st; pos={}
        while cur not in seen and cur not in pos:
            pos[cur]=len(path); path.append(cur); cur=x[cur]
        if cur in pos:
            cyc.append(len(path)-pos[cur])
        seen.update(path)
    return tuple(sorted(cyc)), len(cyc)
